use crate::client::{print, Client};
use anyhow::bail;
use den_core::Message;
use std::collections::BTreeMap;

pub(crate) struct Args {
    pub channel: String,
    pub before: Option<String>,
    pub after: Option<String>,
    pub limit: u32,
    pub all: bool,
}

/// Reject impossible queries before any HTTP request, one page or all.
pub(crate) fn validate(before: Option<&str>, after: Option<&str>, limit: u32) -> anyhow::Result<()> {
    anyhow::ensure!(
        before.is_none() || after.is_none(),
        "Use --before or --after, not both"
    );
    anyhow::ensure!((1..=200).contains(&limit), "Limit must be 1-200");

